import React, { useState, useEffect } from 'react';

const CounterApp = () => {
  const [startingNumber, setStartingNumber] = useState(0);
  const [upperBound, setUpperBound] = useState(10);
  const [speed, setSpeed] = useState(1000); // Default to 1 second
  const [currentNumber, setCurrentNumber] = useState(0);
  const [isRunning, setIsRunning] = useState(false);

  useEffect(() => {
    let interval;
    if (isRunning) {
      interval = setInterval(() => {
        setCurrentNumber((prev) =>
          prev < upperBound ? prev + 1 : parseInt(startingNumber, 10)
        );
      }, speed);
    }
    return () => clearInterval(interval);
  }, [isRunning, speed, upperBound, startingNumber]);

  const handleStart = () => {
    setCurrentNumber(parseInt(startingNumber, 10)); // Reset to starting number
    setIsRunning(true); // Start counting
  };

  const handleChangeNumber = (e) => {
    setStartingNumber(e.target.value);
  };

  const handleChangeUpperBound = (e) => {
    setUpperBound(e.target.value);
  };

  const handleChangeSpeed = (e) => {
    setSpeed(parseInt(e.target.value, 10));
  };

  return (
    <div style={{ textAlign: 'center', marginTop: '50px' }}>
      <h1>React Counter with Upper Bound</h1>
      <div>
        <label>
          Starting Number:
          <input
            type="number"
            value={startingNumber}
            onChange={handleChangeNumber}
          />
        </label>
      </div>
      <div>
        <label>
          Upper Bound:
          <input
            type="number"
            value={upperBound}
            onChange={handleChangeUpperBound}
          />
        </label>
      </div>
      <div>
        <label>
          Speed (ms):
          <input
            type="number"
            value={speed}
            onChange={handleChangeSpeed}
          />
        </label>
      </div>
      <button onClick={handleStart}>Start</button>
      <h2 style={{fontSize: 50}}>{currentNumber}</h2>
    </div>
  );
};

export default CounterApp;

